pub fn simple_nested(a: &mut Vec<i32>, b: &Vec<i32>, N: i32) -> i32 {
    // We assume:
    //   1. a.len() == N as usize
    //   2. b.len() == N as usize
    //   3. For every index i in [0, N), b[i] is either i or i+1.
    //
    // Under these assumptions, we update a[i]:
    //   - set a[i] = 1 if b[i] == i
    //   - set a[i] = 2 if b[i] == i + 1
    // and accumulate the sum of those values.
    //
    // Since N ≤ 0x3FFF_FFFF, the maximum sum is 2*N ≤ 0x7FFF_FFFE, which fits in i32.

    let mut sum: i32 = 0;
    let n = N as usize;

    // Iterate over indices 0..N
    for i in 0..n {
        // Compare b[i] to i (as i32). If equal, write 1; otherwise write 2.
        let val = if b[i] == i as i32 { 1 } else { 2 };
        a[i] = val;
        sum += val;
    }

    sum
}